import { addDaysISO, daysBetween, type ISODate } from '../../domain/dates';
import type { CompanionSpecies, SupportedLanguage } from '../../domain/entities';
import type { SeedResult } from '../seed';

/**
 * Synthetic demo personas. One file per persona:
 *   apps/mobile/assets/personas/<id>/core.json   (schema: assets/personas/core.schema.json)
 * Files are generated by tools/synthetic. The app NEVER reads ground_truth/.
 *
 * To add one: drop the file in assets/personas/<id>/ and register it in PERSONA_FILES below.
 */
export interface PersonaMeta {
  id: string;
  /** Shown in the demo picker, e.g. "Aino, 42, post-TMS". */
  label: string;
  /** Scenario codes from the spec (demo script only; the app does not branch on them). */
  path?: string;
  state?: string;
  /** One line for the picker, e.g. "Drift, walks help". */
  story?: string;
  language?: SupportedLanguage;
  companion?: { species: CompanionSpecies; name: string };
  /** Set by the clinic only. Enables the upwardDrift rule. */
  bipolarFlag?: boolean;
  /** FICTIONAL contact. */
  trustedContact?: { name: string; phone: string };
}

export interface Persona extends SeedResult {
  synthetic: true;
  generatorVersion?: string;
  seed?: number;
  persona: PersonaMeta;
}

const DATE = /^\d{4}-\d{2}-\d{2}$/;
const TIME = /^([01]\d|2[0-3]):[0-5]\d$/;

/** Runtime validation so a malformed file fails loudly in dev instead of breaking the demo. */
export function parsePersona(raw: unknown): Persona {
  const p = raw as Partial<Persona> & { persona?: Partial<PersonaMeta> & { displayName?: string } };
  if (!p || typeof p !== 'object') throw new Error('Persona: not an object');
  if (p.synthetic !== true) throw new Error('Persona: "synthetic": true is required (synthetic data only)');
  const label = p.persona?.label ?? p.persona?.displayName;
  if (!p.persona?.id || !label) throw new Error('Persona: missing persona.id / persona.label');
  const id = p.persona.id;
  if (!Array.isArray(p.checkIns) || !Array.isArray(p.sensors) || !Array.isArray(p.feedback)) {
    throw new Error(`Persona ${id}: checkIns, sensors and feedback must be arrays`);
  }
  for (const c of p.checkIns) {
    if (!DATE.test(c.date) || !Number.isInteger(c.mood) || c.mood < 1 || c.mood > 5 || typeof c.safetyConcern !== 'boolean') {
      throw new Error(`Persona ${id}: invalid check-in ${c.id}`);
    }
  }
  for (const s of p.sensors) {
    if (!DATE.test(s.date)) throw new Error(`Persona ${id}: invalid sensor date ${s.date}`);
    if (s.bedtime !== undefined && !TIME.test(s.bedtime)) throw new Error(`Persona ${id}: bedtime must be "HH:mm" (${s.date})`);
  }
  for (const q of p.phq9 ?? []) {
    const okItems = Array.isArray(q.items) && q.items.length === 9 && q.items.every((v) => Number.isInteger(v) && v >= 0 && v <= 3);
    if (!DATE.test(q.date) || !okItems || q.total !== q.items.reduce((a, b) => a + b, 0)) {
      throw new Error(`Persona ${id}: invalid PHQ-9 entry ${q.date} (9 items 0–3, total = sum)`);
    }
  }
  return { ...(p as Persona), persona: { ...(p.persona as PersonaMeta), label } };
}

/**
 * Files keep real calendar dates. When a persona is loaded, every date is moved by the same
 * number of days so that the LAST day of the file lands on `endDate` (normally "yesterday").
 * That keeps weekdays/gaps intact and works with the demo's "Advance 1 day".
 */
export function rebasePersona<T extends SeedResult>(data: T, endDate: ISODate): T {
  const dates = [
    ...data.checkIns.map((c) => c.date),
    ...data.sensors.map((s) => s.date),
    ...data.feedback.map((f) => f.date),
    ...(data.phq9 ?? []).map((q) => q.date),
  ];
  if (dates.length === 0) return data;
  const last = dates.reduce((max, d) => (d > max ? d : max));
  const shift = daysBetween(last, endDate);
  if (shift === 0) return data;
  const move = (d: ISODate) => addDaysISO(d, shift);
  const moveTime = (iso: string) => {
    const t = new Date(iso).getTime();
    return Number.isNaN(t) ? iso : new Date(t + shift * 86_400_000).toISOString();
  };
  return {
    ...data,
    checkIns: data.checkIns.map((c) => ({ ...c, date: move(c.date), createdAt: moveTime(c.createdAt) })),
    sensors: data.sensors.map((s) => ({ ...s, date: move(s.date) })),
    feedback: data.feedback.map((f) => ({ ...f, date: move(f.date) })),
    phq9: data.phq9?.map((q) => ({ ...q, date: move(q.date) })),
  };
}

/** Registered persona files (static requires so Metro bundles them). */
const PERSONA_FILES: unknown[] = [
  // require('../../../assets/personas/aino/core.json'),
];

export const PERSONAS: Persona[] = PERSONA_FILES.map(parsePersona);
